/* Token Radar: a dark radar-desk page. One palette, one spacing scale, system type. */
:root {
  --bg: #0a0f1a;
  --panel: #101828;
  --panel-2: #0d1526;
  --line: #1e2a3f;
  --line-soft: #16213a;
  --text: #e6edf7;
  --muted: #93a1b8;
  --faint: #64748b;
  --green: #34d399;
  --green-dim: #0e3b2e;
  --cyan: #22d3ee;
  --amber: #fbbf24;
  --amber-dim: #3d2f07;
  --red: #f87171;
  --chip: #182238;
  --radius: 10px;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
}
* { box-sizing: border-box; }
html { background: var(--bg); }
body { margin: 0; background: var(--bg); color: var(--text); font-family: var(--sans); font-size: 15px; line-height: 1.5; }
a { color: var(--cyan); }
.skip { position: absolute; left: -999px; top: 0; background: var(--green); color: #04120c; padding: 8px 12px; border-radius: 0 0 8px 0; }
.skip:focus { left: 0; }
.shell { max-width: 1160px; margin: 0 auto; padding: 20px 20px 48px; }
.num { font-family: var(--mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
.sub { color: var(--muted); font-size: 13px; }
.pos { color: var(--green); }
.neg { color: var(--red); }

/* header */
.top { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; justify-content: space-between; padding: 6px 0 18px; border-bottom: 1px solid var(--line); }
.brand { display: flex; align-items: center; gap: 12px; }
.mark { width: 34px; height: 34px; border-radius: 50%; flex: none; background: radial-gradient(circle at 50% 50%, transparent 0 8px, var(--green) 8px 9px, transparent 9px 14px, var(--green) 14px 15px, transparent 15px 20px, rgba(52, 211, 153, .45) 20px 21px, transparent 21px), radial-gradient(circle at 65% 35%, var(--green) 0 3px, transparent 4px); border: 1px solid rgba(52, 211, 153, .5); }
.brand-name { font-weight: 700; letter-spacing: .02em; font-size: 19px; }
.brand-name small { display: block; font-size: 11px; font-weight: 600; letter-spacing: .14em; text-transform: uppercase; color: var(--green); }
.top-meta { display: flex; gap: 8px; flex-wrap: wrap; }
.top-meta span { background: var(--chip); border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px; font-size: 12px; color: var(--muted); font-family: var(--mono); }

/* lede */
.lede { display: grid; grid-template-columns: 1.25fr 1fr; gap: 20px; padding: 22px 0 8px; }
.lede h1 { font-size: 27px; line-height: 1.25; margin: 0 0 8px; letter-spacing: -.01em; }
.lede h1 em { font-style: normal; color: var(--green); }
.lede p { margin: 0; color: var(--muted); max-width: 56ch; }
.facts { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; align-content: start; }
.fact { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 12px; }
.fact span { display: block; font-size: 12px; color: var(--muted); }
.fact b { font-size: 21px; font-family: var(--mono); font-weight: 700; }
.fact b small { font-size: 12px; color: var(--muted); font-weight: 400; }
.chart { grid-column: 1 / -1; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px 10px; }
.chart h2 { font-size: 13px; margin: 0 0 8px; color: var(--muted); font-weight: 600; letter-spacing: .06em; text-transform: uppercase; }
.chart .bar-row { display: grid; grid-template-columns: 190px 1fr 92px; gap: 10px; align-items: center; padding: 3px 0; font-size: 13px; }
.chart .bar-row .nm { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chart .bar-track { height: 9px; background: var(--chip); border-radius: 99px; overflow: hidden; }
.chart .bar-track i { display: block; height: 100%; background: linear-gradient(90deg, var(--green), var(--cyan)); border-radius: 99px; }
.chart .bar-row .num { text-align: right; font-size: 13px; }

/* controls */
.controls { display: flex; flex-wrap: wrap; gap: 10px; align-items: end; padding: 14px 0; }
.field { display: flex; flex-direction: column; gap: 4px; }
.field label, .field .sub { font-size: 12px; color: var(--muted); }
.field.grow { flex: 1 1 220px; }
input[type="search"], select { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; font: inherit; font-size: 14px; }
input[type="search"]:focus, select:focus, button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 1px; }
.tabs { display: flex; gap: 6px; }
.tabs button, .button { background: var(--chip); color: var(--text); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; font: inherit; font-size: 14px; cursor: pointer; }
.tabs button[aria-pressed="true"] { background: var(--green-dim); border-color: var(--green); color: var(--green); }
.check { display: flex; align-items: center; gap: 6px; font-size: 14px; color: var(--text); padding: 8px 2px; cursor: pointer; }
.check input { accent-color: var(--green); width: 16px; height: 16px; }
.count { margin-left: auto; align-self: center; color: var(--muted); font-size: 13px; font-family: var(--mono); }

/* table */
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: 12px 14px; color: var(--muted); font-size: 13px; border-bottom: 1px solid var(--line-soft); }
thead th { text-align: left; font-size: 12px; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); border-bottom: 1px solid var(--line); padding: 10px 12px; white-space: nowrap; }
thead th button { background: none; border: 0; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; cursor: pointer; padding: 0; }
thead th button:hover { color: var(--text); }
tbody td { padding: 10px 12px; border-bottom: 1px solid var(--line-soft); vertical-align: middle; }
tbody tr { cursor: pointer; }
tbody tr:hover, tbody tr:focus-visible { background: var(--panel-2); }
tbody tr[data-selected="true"] { background: var(--green-dim); }
tbody tr:last-child td { border-bottom: 0; }
td.num, th.num { text-align: right; }
.name b { display: block; font-weight: 650; }
.name .sub { display: block; }
.wl { display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--green); border: 1px solid var(--green); border-radius: 4px; padding: 1px 5px; margin-left: 6px; vertical-align: 1px; }
.implied { display: flex; align-items: center; gap: 8px; justify-content: flex-end; }
.implied .bar { width: 74px; height: 7px; background: var(--chip); border-radius: 99px; overflow: hidden; flex: none; }
.implied .bar i { display: block; height: 100%; background: var(--green); border-radius: 99px; }
.status { display: inline-block; font-size: 12px; color: var(--amber); background: var(--amber-dim); border: 1px solid rgba(251, 191, 36, .35); border-radius: 999px; padding: 2px 8px; white-space: nowrap; }
.status.live { color: var(--cyan); background: rgba(34, 211, 238, .08); border-color: rgba(34, 211, 238, .35); }
.conf { display: inline-block; font-size: 11px; font-weight: 700; border-radius: 999px; padding: 2px 8px; }
.conf.high { color: var(--green); background: var(--green-dim); }
.conf.medium { color: var(--amber); background: var(--amber-dim); }
.conf.low { color: var(--muted); background: var(--chip); }
.more { display: block; margin: 0 auto; }
.pager { padding: 14px; text-align: center; }
.empty { padding: 40px 20px; text-align: center; }
.empty h2 { margin: 0 0 6px; }
.empty p { color: var(--muted); margin: 0 0 16px; }
.button.primary { background: var(--green); color: #04120c; border-color: var(--green); font-weight: 650; }

/* sections */
section.panel { margin-top: 18px; padding: 18px 20px; }
section.panel h2 { margin: 0 0 6px; font-size: 18px; }
section.panel h3 { margin: 18px 0 8px; font-size: 14px; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); }
section.panel p { margin: 0 0 10px; color: var(--muted); max-width: 72ch; }
.formula { font-family: var(--mono); font-size: 13px; background: var(--panel-2); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px; overflow-x: auto; white-space: nowrap; color: var(--text); }
.compact td, .compact th { padding: 7px 10px; }
.compact tbody tr { cursor: default; }

/* detail dialog */
dialog.detail { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 14px; padding: 0; width: min(680px, calc(100vw - 32px)); max-height: calc(100vh - 48px); overflow: auto; }
dialog.detail::backdrop { background: rgba(2, 6, 16, .72); }
.detail-head { display: flex; justify-content: space-between; gap: 14px; padding: 20px 22px 0; }
.detail-head h2 { margin: 4px 0 2px; font-size: 23px; }
.detail-head .rankline { font-size: 12px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--green); }
.close { background: var(--chip); color: var(--text); border: 1px solid var(--line); border-radius: 8px; padding: 7px 12px; font: inherit; font-size: 13px; cursor: pointer; height: fit-content; }
.detail-section { padding: 16px 22px 4px; }
.detail-section:last-child { padding-bottom: 22px; }
.detail-section h3 { font-size: 13px; letter-spacing: .06em; text-transform: uppercase; color: var(--muted); margin: 0 0 10px; }
.equation { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--line-soft); border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.equation > div { background: var(--panel-2); padding: 9px 12px; display: flex; justify-content: space-between; gap: 10px; font-size: 13px; }
.equation span { color: var(--muted); }
.equation b { font-size: 14px; }
.equation .total { grid-column: 1 / -1; background: var(--green-dim); }
.equation .total b { color: var(--green); }
.flags { display: flex; flex-wrap: wrap; gap: 6px; margin: 0 0 4px; padding: 0; list-style: none; }
.flags li { font-size: 12px; color: var(--amber); background: var(--amber-dim); border: 1px solid rgba(251, 191, 36, .3); border-radius: 999px; padding: 3px 9px; }
.flags li.ok { color: var(--green); background: var(--green-dim); border-color: rgba(52, 211, 153, .3); }
ol.steps { margin: 0; padding-left: 22px; display: grid; gap: 10px; }
ol.steps li::marker { color: var(--green); font-weight: 700; font-family: var(--mono); }
ol.steps b { display: block; font-weight: 550; }
ol.steps .cost { color: var(--muted); font-size: 13px; }
.peer-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.peer-table th, .peer-table td { text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--line-soft); }
.peer-table th { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: .05em; }
.peer-table td.num, .peer-table th.num { text-align: right; }

footer { margin-top: 22px; color: var(--faint); font-size: 12px; }
footer p { margin: 4px 0; }

@media (max-width: 760px) {
  .lede { grid-template-columns: 1fr; }
  .chart .bar-row { grid-template-columns: 130px 1fr 78px; }
  .equation { grid-template-columns: 1fr; }
  .count { margin-left: 0; }
}
